      "summary": "確立機關資訊資產風險管理制度。落實資產清冊維護，針對硬體、軟體、資料、人員、文件、環境六大類資產進行機密性 (C)、完整性 (I)、可用性 (A) 三維度量化打分；套用風險矩陣計算不可接受風險 (分值 >= 8分)；擬定具體降低風險之風險處置計畫 (RTP)；並產製適用性聲明書 (SOA, MS-4-16)，逐條載明 ISO 27001 附錄控制措施之採納狀態與實施佐證。",
